    let t: u32 = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let arr: Vec<u64> = lines.next().unwrap().unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();

        let mut maxes = vec![0; n + 1];
        for (i, &value) in arr.iter().enumerate() {
            maxes[i + 1] = maxes[i].max(value);
        }

        let mut mins = vec![u64::MAX; n + 1];
        mins[n] = u64::MAX;
        for i in (0..n).rev() {
            mins[i] = mins[i + 1].min(arr[i]);
        }

        let can_not_sort = (1..n).any(|i| maxes[i] > mins[i]);
        println!("{}", if can_not_sort { "YES" } else { "NO" });
    }
}

