use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let k: usize = lines.next().unwrap().trim().parse().unwrap();
    let n = (1 << k) - 1;
    let mut a = vec![0; n];
    let mut r = vec![0; n];

    for (i, ch) in lines.next().unwrap().chars().rev().enumerate().take(n) {
        r[i] = match ch {
            '0' => 0,
            '1' => 1,
            '?' => 2,
            _ => unreachable!(),
        };
    }

    for i in (0..n).rev() {
        a[i] = if i * 2 + 1 >= n {
            if r[i] == 2 { 2 } else { 1 }
        } else {
            match r[i] {
                0 => a[i * 2 + 2],
                1 => a[i * 2 + 1],
                2 => a[i * 2 + 2] + a[i * 2 + 1],
                _ => unreachable!(),
            }
        };
    }

    let q: usize = lines.next().unwrap().trim().parse().unwrap();
    for _ in 0..q {
        let mut query = String::new();
        io::stdin().read_line(&mut query).unwrap();
        let mut parts = query.split_whitespace();
        let p: usize = parts.next().unwrap().parse().unwrap();
        let c = parts.next().unwrap().chars().next().unwrap();
        let mut i = n - p;
        r[i] = match c {
            '0' => 0,
            '1' => 1,
            '?' => 2,
            _ => unreachable!(),
        };

        loop {
            let prev = a[i];
            a[i] = if i * 2 + 1 >= n {
                if r[i] == 2 { 2 } else { 1 }
            } else {
                match r[i] {
                    0 => a[i * 2 + 2],
                    1 => a[i * 2 + 1],
                    2 => a[i * 2 + 2] + a[i * 2 + 1],
                    _ => unreachable!(),
                }
            };
            if i == 0 || a[i] == prev {
                break;
            }
            i = (i - 1) / 2;
        }
        writeln!(io::stdout(), "{}", a[0]).unwrap();
    }
}

