fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let mut sum = [0; 1000];
    let mut sum1 = [0; 1000];
    let mut grid = vec![0; 1000 * 1000];

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let m = first_line[1];

    for _ in 0..n {
        let line: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let x = line[0];
        let y = line[1];
        let index = (y - 1) * 1000 + (x - 1);
        grid[index] += 1;
        sum[y - 1] += 1;
    }

    let mut u = 0;
    let mut v = 0;

    for _ in 0..m {
        let line: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let x = line[0];
        let y = line[1];
        let index = (y - 1) * 1000 + (x - 1);
        if grid[index] != 0 {
            grid[index] -= 1;
            v += 1;
            u += 1;
            sum[y - 1] -= 1;
        } else {
            sum1[y - 1] += 1;
        }
    }

    for i in 0..1000 {
