int digits[] = {0, 0, 1, 7, 4, 5, 9, 8};

int main()
{
    int n, i, j, start;
    scanf("%d", &n);

    int *d = (int*)calloc(sizeof(int), n + 1);
    int *last = (int*)calloc(sizeof(int), n + 1);

    d[0] = 1;
    for (i = 0; i < nseg; ++i) {
        int curr_dig = digits[segments[i]];
        for (j = 0; j + segments[i] <= n; ++j) {
            if (d[j] > 0) {
                int next = j + segments[i];
                int new_d = d[j] + 1;
                int last_dig = digits[last[next]];

                if (new_d > d[next] ||
                     (new_d == d[next] && curr_dig > last_dig))
                {
                    d[next] = new_d;
                    last[next] = segments[i];
                }
            }
        }
    }

    start = 0;
    for (i = 1; i <= n; ++i) {
        if (d[i] > d[start] ||
            (d[i] == d[start] && segments[last[i]] > segments[last[start]]))
        {
            start = i;
        }
    }

    while (start != 0) {
        printf("%d", digits[last[start]]);
        start -= last[start];
    }

    return 0;
}

