use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let mut sum = vec![-1; 1000];
    let mut j = 0;

    if let Some(Ok(x_str)) = lines.next() {
        if let Ok(mut x) = x_str.parse::<i32>() {
            while x > 0 {
                x -= 1;
                if let Some(Ok(n_str)) = lines.next() {
                    if let Ok(n) = n_str.parse::<usize>() {
                        let mut a: Vec<i32> = Vec::with_capacity(n);
                        for _ in 0..n {
                            if let Some(Ok(num_str)) = lines.next() {
                                if let Ok(num) = num_str.parse::<i32>() {
                                    a.push(num);
                                }
                            }
                        }
                        a.sort();
                        let min = a[0];
                        let step = min * 2 - 1;
                        sum[j] = 0;
                        for &num in a.iter().rev() {
                            if num >= step {
                                sum[j] += if num % step == 0 {
                                    num / step - 1
                                } else {
                                    num / step
                                };
                            }
                        }
                        j += 1;
                    }
                }
            }
        }
    }

    for &s in &sum {
        if s == -1 {
            break;
        }
        println!("{}", s);
    }
}

