                if (*(inRaws + i) >= 2) {
                    if (*(inRaws + i) == 2) {
                        *(inRawsP + i) = 1;
                    }
                    else {
                        *(inRawsP + i) = *(inRawsP + i) + *(inRaws + i) - 1;
