use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let nr_rows: usize = input.trim().parse().expect("Please enter a valid number");

    let mut buf2 = vec![0; nr_rows * 6];
    let mut rdlen = 0;

    for _ in 0..nr_rows {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let trimmed = input.trim();
        if trimmed.len() > 5 {
            eprintln!("Input too long, expected at most 5 characters");
            return Ok(());
        }
        buf2[rdlen..rdlen + trimmed.len()].copy_from_slice(trimmed.as_bytes());
        rdlen += trimmed.len();
        buf2[rdlen] = b'\n';
        rdlen += 1;
    }

    if let Some(pos) = buf2.windows(2).position(|w| w == b"OO") {
        buf2[pos..pos + 2].copy_from_slice(b"++");
        println!("YES");
        io::stdout().write_all(&buf2[..rdlen - 1])?;
    } else {
        println!("NO");
    }

    Ok(())
}

