        println!("NO");
        return;
    }

    let mut fr = [0; 26];
    let mut diff = 0;

    for (a, b) in aa.chars().zip(bb.chars()) {
        if a != b {
            fr[(a as u8 - b'a') as usize] += 1;
            fr[(b as u8 - b'a') as usize] -= 1;
            diff += 1;
        }
    }

    let good = fr.iter().all(|&x| x == 0);
    println!("{}", if good && diff == 2 { "YES" } else { "NO" });
}

