fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut dplast = vec![0; m + 1];
    let mut dpcurt = vec![0; m + 1];
    let mut buf = vec![0; m];

    for i in 0..n {
        if i & 1 == 1 {
            let mut sum: i64 = 0;
            for j in 0..m {
                buf[j] = lines.next().unwrap().parse().unwrap();
                sum += buf[j];
            }
            let mut maxlast = dplast[m];
            for j in (1..=m).rev() {
                sum -= buf[j - 1];
                if dplast[j] > maxlast {
                    maxlast = dplast[j];
                }
                dpcurt[j] = sum + maxlast;
            }
        } else {
            let mut sum: i64 = lines.next().unwrap().parse().unwrap();
            let mut maxlast = dplast[1];
            for j in 2..=m {
                let num: i64 = lines.next().unwrap().parse().unwrap();
                sum += num;
                if dplast[j - 1] > maxlast {
                    maxlast = dplast[j - 1];
                }
                dpcurt[j] = sum + maxlast;
            }
        }
        std::mem::swap(&mut dplast, &mut dpcurt);
    }

    let start = if n & 1 == 1 { 2 } else { 1 };
    let end = if n & 1 == 1 { m } else { m - 1 };
    let mut ans = -1000000000000;
    for i in start..=end {
        if dplast[i] > ans {
            ans = dplast[i];
        }
    }

    println!("{}", ans);
}

