use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut arr: Vec<usize> = vec![0; n + 1];
    for (i, line) in lines.by_ref().take(n).enumerate() {
        arr[i + 1] = line.parse().unwrap();
    }

    let q: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..q {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let start: usize = parts.next().unwrap().parse().unwrap();
        let end: usize = parts.next().unwrap().parse().unwrap();

        for j in start..=((start + end) / 2) {
            arr.swap(j, end + start - j);
        }

        let mut is_visited = vec![false; n + 1];
        let mut components = 0;

        for j in 1..=n {
            if !is_visited[j] {
                is_visited[j] = true;
                let mut chain = arr[j];
                let mut size = 1;

                while j != chain {
                    is_visited[chain] = true;
                    chain = arr[chain];
                    size += 1;
                }

                components += size - 1;
            }
        }

        if components % 2 == 1 {
            println!("odd");
        } else {
            println!("even");
        }
    }
}

