#include <stdlib.h>

static int sum[1000] = {0};
static int sum1[1000] = {0};

int main(void)
{
	int n, m;
	int x, y;
	int i;
	int u = 0, v = 0;
	int *ptr = (int*)malloc(sizeof(int) * 1000000);
	int *tmp_ptr = ptr;
	int tmp;

	for (i = 0; i < 1000000; i++) {
		*tmp_ptr = 0;
		tmp_ptr++;
	}

	scanf("%d %d", &n, &m);

	for (i = 0; i < n; i++) {
		scanf("%d %d", &x, &y);
		tmp_ptr = (ptr + (long int)((long int)((y - 1) * 1000) + x - 1));

		(*tmp_ptr)++;
		sum[y - 1]++;
	}



	for (i = 0; i < m; i++) {
		scanf("%d %d", &x, &y);

		tmp = *(ptr + (long int)((y - 1) * 1000) + x - 1);


		if (tmp != 0) {

			tmp_ptr = (ptr + (long int)((y - 1) * 1000) + x - 1);
			(*tmp_ptr)--;
			v++;
			u++;
			sum[y - 1]--;
		}
		else
			sum1[y - 1]++;
	}

	for (i = 0; i < 1000; i++) {
		if (sum[i] <= sum1[i])
			u += sum[i];
		else
			u += sum1[i];
	}

	printf("%d %d\n", u, v);
	free(ptr);
	return 0;
}

