    printf("%d\n", frp - flp);
    for (int *p = a; p < a + flp; p++) {
        printf("%d ", *p);
    }
    for (int i = flp; i < frp; i++) {
        printf("1 ");
    }
    for (int *p = a + frp; p < a + n; p++) {
        printf("%d ", *p);
    }

    return 0;
