        for j in start..=((start + end) / 2) {
            arr.swap(j, end + start - j);
        }

        let mut is_visited = vec![false; n + 1];
        let mut components = 0;

        for j in 1..=n {
            if !is_visited[j] {
                is_visited[j] = true;
                let mut chain = arr[j];
                let mut size = 1;

                while j != chain {
                    is_visited[chain] = true;
                    chain = arr[chain];
                    size += 1;
                }

                components += size - 1;
            }
        }

        if components % 2 == 1 {
            println!("odd");
        } else {
            println!("even");
        }
    }
}

