    let (p, q, l, r) = (first_line[0], first_line[1], first_line[2], first_line[3]);

    let mut a: Vec<Pair> = Vec::with_capacity(p as usize);
    let mut b: Vec<Pair> = Vec::with_capacity(q as usize);

    for _ in 0..p {
        let line: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        a.push(Pair { s: line[0], f: line[1] });
    }

    for _ in 0..q {
        let line: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        b.push(Pair { s: line[0], f: line[1] });
    }

    let mut cnt = 0;

    for k in l..=r {
        let mut flag = false;
        for bj in &b {
            for ai in &a {
                if (bj.s + k <= ai.f && bj.s + k >= ai.s) ||
