use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut columns = Vec::with_capacity(n);
    let mut l_total = 0;
    let mut r_total = 0;

    for _ in 0..n {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let left: i32 = parts.next().unwrap().parse().unwrap();
        let right: i32 = parts.next().unwrap().parse().unwrap();
        columns.push((left, right));
        l_total += left as i64;
        r_total += right as i64;
    }

    let s_beauty = (l_total - r_total).abs();
    let mut b_inc = 0;
    let mut sol = 0;

    for (i, &(left, right)) in columns.iter().enumerate() {
        let c_beauty = ((l_total - left as i64 + right as i64) - (r_total - right as i64 + left as i64)).abs();
        if c_beauty > s_beauty && c_beauty - s_beauty > b_inc {
            b_inc = c_beauty - s_beauty;
            sol = i + 1;
        }
    }

    println!("{}", sol);
}

