    while let Some(&ch) = chars.peek() {
        if ch == '\n' {
            break;
        }
        *tail = Some(Box::new(Node { val: ch, next: None }));
        tail = &mut tail.as_mut().unwrap().next;
        chars.next();
    }

    let mut flag_0 = false;
    let mut flag_1 = false;
    let mut current = head.as_ref();

    while let Some(node) = current {
        if node.val == '0' {
            println!("{}", if flag_0 { "1 1" } else { "3 1" });
            flag_0 = !flag_0;
        } else {
            println!("{}", if flag_1 { "1 1" } else { "1 3" });
            flag_1 = !flag_1;
        }
        current = node.next.as_ref();
    }
}

